		const results = [];
		const sessionCache = getWorkingSessionTranscriptMessageMap(sessionId);
		if (!sessionCache) return results;
		for (const message of sessionCache.values()) {
			if (message.messageType !== "assistant") continue;
			for (const content of message.content) {
				if (content.type !== "tool-call" || !("tool" in content) || !content.tool) continue;
				const tool = content.tool;
				if (this.isAskUserQuestionToolName(tool.name)) continue;
				const perm = tool.metaData?.acp_request_permission;
				if (perm?.requestId && tool.status === "pending") results.push({
					toolCallId: tool.id,
					requestId: perm.requestId
				});
			}
		}
