	async getCloudAgentSandboxSession(params) {
		const asConversationId = String(params.asConversationId);
		const existing = this.cloudAgentSandboxSessionRequests.get(asConversationId);
		if (existing) return existing;
		const request = this.getDaemonClientFeature("cloudAgentGetSandboxSession")(params);
		this.cloudAgentSandboxSessionRequests.set(asConversationId, request);
		request.then(() => {
			setTimeout(() => {
				if (this.cloudAgentSandboxSessionRequests.get(asConversationId) === request) this.cloudAgentSandboxSessionRequests.delete(asConversationId);
			}, CLOUD_AGENT_SANDBOX_SESSION_DEDUPE_TTL_MS);
		}, () => {
			if (this.cloudAgentSandboxSessionRequests.get(asConversationId) === request) this.cloudAgentSandboxSessionRequests.delete(asConversationId);
		});
		return request;
	}
	/**
	* 公开的 URL 预览解析方法（HTML 产物统一 Webview 预览方案）。
	* 供 UI 层（如 detail-panel-wrapper）在 artifact 点击时调用，
	* 将 agent:// 沙箱 URL 解析为 sandbox-preview 本地代理 URL。
	* 非 agent:// 的 URL 原样返回。
	*/
	async resolvePreviewUrl(sessionId, url) {
		return this.resolveBrowserUrl(sessionId, url);
	}
	/**
	* 用调用方已持有的 sandbox 凭据解析 agent:// URL，跳过 getCloudAgentSandboxSession。
	*
	* resolveBrowserUrl 按 sessionId 反查凭据时要求传入 asConversationId=conversation.runtimeId，
	* 而不是子 session 自己的 sessionId（issue #54526：误用导致 404/凭据错配）。同事助理等场景在
	* 渲染端（use-colleague-agent-chat）已经持有正确的 sandboxCredential，直接传下来即可，
	* 不需要、也不应该让 adapter 再按 sessionId 去猜 runtimeId。
	*/
	async resolvePreviewUrlWithSandbox(sandbox, url) {
		if (!url.startsWith("agent://")) return url;
		return this.resolveAgentUrlWithSandboxCredential(sandbox, url, "with-sandbox");
	}
	/**
	* 内部 URL 解析逻辑。
	*
	* 对于 cloud agent（云助理/企业智能体/Teams）会话的 HTML 产物 URL，
	* 通过 sandboxPreview:registerMount 转为本地代理 URL，
	* 使 webview 能正确加载受 CSP 保护的沙箱文件。
	*
	* 实际 URL 格式（从代码库验证）：
	*   - 本地会话：file:///Users/... 或 http://127.0.0.1:PORT/static-html/...
	*   - Cloud Agent：agent:///workspace/path.html（sandbox-proxy 产生）
	*   - IDE plugin：agent://files/path（file-changes 产物）
	*
	* 对于不需要 proxy 的 URL，原样返回。
	*/
	async resolveBrowserUrl(sessionId, url) {
		if (!url.startsWith("agent://")) return url;
		const sandbox = await this.getCloudAgentSandboxSession({ asConversationId: sessionId }).catch(() => void 0);
		if (!sandbox?.link || !sandbox?.token) {
			console.warn("[WorkbuddyAdapter] resolveBrowserUrl: no sandbox credentials", {
				sessionId,
				hasLink: !!sandbox?.link,
				hasToken: !!sandbox?.token
			});
			return url;
		}
		return this.resolveAgentUrlWithSandboxCredential(sandbox, url, sessionId);
	}
	/**
	* 拿到 sandbox 凭据之后的共用解析逻辑：文件路径解析 + sandboxPreview:registerMount + 拼接
	* 本地代理 URL。resolveBrowserUrl（按 sessionId 反查凭据）和 resolvePreviewUrlWithSandbox
	* （调用方直传凭据）共用本方法，避免逻辑分叉。
	*/
	async resolveAgentUrlWithSandboxCredential(sandbox, url, logSessionId) {
		const dc = this.daemonClient;
		if (!dc || typeof dc.sandboxPreviewRegisterMount !== "function") {
			console.warn("[WorkbuddyAdapter] resolveAgentUrlWithSandboxCredential: daemon client unavailable", {
				sessionId: logSessionId,
				hasDc: !!dc
			});
			return url;
		}
		try {
			const filePath = resolveSandboxPreviewFilePath(url, sandbox.cwd || "/workspace");
			if (!filePath) {
				console.warn("[WorkbuddyAdapter] resolveAgentUrlWithSandboxCredential: unknown agent:// url format", {
					sessionId: logSessionId,
					url: url.slice(0, 100)
				});
				return url;
			}
			const result = await dc.sandboxPreviewRegisterMount({
				source: "colleague",
				sessionId: logSessionId,
				sandbox: {
					link: sandbox.link,
					token: sandbox.token,
					sandboxId: sandbox.sandboxId
				},
				root: "/"
			});
			if (result?.ok && result?.baseUrl) return result.baseUrl + encodeURI(toSandboxPreviewProxyPath(filePath));
			console.warn("[WorkbuddyAdapter] resolveAgentUrlWithSandboxCredential: mount failed", {
				sessionId: logSessionId,
				result
			});
			return url;
		} catch (err) {
			console.error("[WorkbuddyAdapter] resolveAgentUrlWithSandboxCredential: mount error", {
				sessionId: logSessionId,
				error: err?.message || String(err)
			});
		}
		return url;
	}
