	async fileToBase64(file) {
		const bytes = new Uint8Array(await file.arrayBuffer());
		const chunkSize = 32768;
		let binary = "";
		for (let i = 0; i < bytes.length; i += chunkSize) binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
		return btoa(binary);
	}
