	deleteExplicitSessionViaDaemon(sessionId, operation) {
		const pending = this.pendingExplicitSessionDeleteRpcs.get(sessionId);
		if (pending) return pending;
		this.markExplicitSessionDeleteRequest(sessionId);
		const deletion = (async () => {
			try {
				if ((await this.requireDaemonClient().deleteSession(sessionId))?.status === "cancelled") {
					this.clearExplicitSessionDeleteRequest(sessionId);
					return {
						success: false,
						cancelled: true
					};
				}
				this.completeExplicitSessionDelete(sessionId, "rpc");
				invalidateArchivedSessionConversations();
				return { success: true };
			} catch (error) {
				if (!this.explicitSessionDeleteRequests.has(sessionId)) return { success: true };
				try {
					if (!await this.requireDaemonClient().getSession(sessionId)) {
						this.completeExplicitSessionDelete(sessionId, "rpc");
						invalidateArchivedSessionConversations();
						return { success: true };
					}
				} catch {}
				console.error(`[WorkbuddyAdapter] ${operation} failed:`, error);
				return {
					success: false,
					error: error instanceof Error ? error.message : "Unknown error"
				};
			}
		})().finally(() => {
			if (this.pendingExplicitSessionDeleteRpcs.get(sessionId) === deletion) this.pendingExplicitSessionDeleteRpcs.delete(sessionId);
		});
		this.pendingExplicitSessionDeleteRpcs.set(sessionId, deletion);
		return deletion;
	}
	async deleteWorkspaceAndFiles(workspacePath) {
		try {
			const workspaceSessions = (await this.listSessionsViaCurrentApi()).agents.filter((s) => s.cwd === workspacePath);
			for (const session of workspaceSessions) {
				const deleteResult = await this.deleteExplicitSessionViaDaemon(session.id, "deleteSessionAndFiles");
				if (deleteResult.cancelled) return {
					success: false,
					error: "Delete cancelled"
				};
				if (!deleteResult.success) return {
					success: false,
					error: deleteResult.error ?? "Unknown error"
				};
			}
			return { success: true };
		} catch (error) {
			console.error("[WorkbuddyAdapter] deleteWorkspaceAndFiles failed:", error);
			return {
				success: false,
				error: error instanceof Error ? error.message : "Unknown error"
			};
		}
	}
