	async listDirectoryEntries(basePath, depth) {
		if (depth <= 0) return [];
		const api = this.requireDaemonClient();
		const listRecursive = async (dirPath, remainingDepth) => {
			if (remainingDepth <= 0) return [];
			const entries = await api.fileListDir(dirPath);
			const normalizedEntries = [];
			for (const entry of entries) {
				if (isFileTreeIgnoredEntry(entry.name)) continue;
				const fullPath = dirPath.endsWith("/") ? `${dirPath}${entry.name}` : `${dirPath}/${entry.name}`;
				normalizedEntries.push({
					name: entry.name,
					path: fullPath,
					type: entry.type === "directory" ? FileType.DIR : FileType.FILE,
					size: entry.size ?? 0,
					mode: 0,
					permissions: "",
					owner: "",
					group: ""
				});
				if (entry.type === "directory" && remainingDepth > 1) normalizedEntries.push(...await listRecursive(fullPath, remainingDepth - 1));
			}
			return normalizedEntries;
		};
		return listRecursive(basePath, depth);
	}
