	async getExpert(expertId, locale = "zh", options) {
		try {
			this.updateExpertLoadState({
				status: "downloading_prompt",
				error: void 0
			});
			const result = await this.getDaemonClientFeature("expertGetExpert")({
				expertId,
				locale,
				...options?.marketExpertId ? { marketExpertId: options.marketExpertId } : {},
				...options?.source ? { source: options.source } : {},
				...options?.enterpriseId ? { enterpriseId: options.enterpriseId } : {}
			});
			if (!result?.expert) throw new Error(`Expert not found: ${expertId}`);
			this.updateExpertLoadState(result.loadState ?? { status: "downloading_prompt_done" });
			const expert = result.expert;
			if (!(locale === "en" ? expert.prompt?.en : expert.prompt?.zh ?? expert.prompt?.en)) try {
				const pluginName = expert.plugin;
				const updatedAt = expert.updatedAt;
				const activationResult = await this.activateExpertPlugin(expertId, pluginName, updatedAt);
				console.log("[WorkbuddyAdapter] getExpert: auto-activated plugin for prompt-empty expert:", {
					expertId,
					success: activationResult.success,
					expertType: activationResult.expertType,
					hasLocalPath: !!activationResult.localPath
				});
				if (activationResult.success) {
					expert.expertType = activationResult.expertType;
					expert.agentName = activationResult.agentName;
					expert.localPath = activationResult.localPath;
					expert.pluginRegisteredName = activationResult.pluginRegisteredName;
					this.markExpertLoaded(expertId);
				}
			} catch (pluginError) {
				console.warn("[WorkbuddyAdapter] getExpert: auto plugin activation failed (non-blocking):", pluginError);
			}
			else this.markExpertLoaded(expertId);
			return expert;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : "Unknown error";
			this.updateExpertLoadState({
				status: "error",
				error: errorMessage
			});
			console.error("[WorkbuddyAdapter] getExpert failed:", error);
			throw new Error(`Failed to get expert "${expertId}": ${errorMessage}`);
		}
	}
