	async clearSelectedExpertForSession(sessionId) {
		const expert = this.selectedExpertBySession.get(sessionId);
		this.selectedExpertBySession.delete(sessionId);
		this.notifySelectedExpertListeners(sessionId, null);
		await this.enqueueExpertSelectionUpdate(sessionId, () => this.disableExpertPluginForSessionBeforeRestart(sessionId, expert, "clearSelectedExpertForSession"));
		const launch = this.sessionLaunchConfig.get(sessionId);
		await this.updateWorkbuddyLaunchConfig(sessionId, {
			mode: "craft",
			expertId: "",
			locale: "",
			runtimeIdentity: ""
		}, launch);
		if (expert?.id) this.deactivateExpertPlugin(expert.id).catch((err) => {
			console.warn("[WorkbuddyAdapter] Failed to deactivate expert plugin on session clear:", err);
		});
	}
	clearSelectedExpertById(expertId) {
		const sessionsToClean = [];
		for (const [sessionId, expert] of this.selectedExpertBySession) if (expert.id === expertId) sessionsToClean.push(sessionId);
		for (const sessionId of sessionsToClean) this.clearSelectedExpertForSession(sessionId).catch((err) => {
			console.warn("[WorkbuddyAdapter] Failed to clear deleted expert from session:", sessionId, err);
		});
	}
	onSelectedExpertChange(callback) {
		this.selectedExpertListeners.add(callback);
		const pendingExpertReplayTimer = setTimeout(() => {
			if (!this.selectedExpertListeners.has(callback)) return;
			const pendingExpert = this.getPendingExpert();
			if (!pendingExpert) return;
			try {
				callback(pendingExpert, void 0);
			} catch {}
		}, 0);
		return () => {
			clearTimeout(pendingExpertReplayTimer);
			this.selectedExpertListeners.delete(callback);
		};
	}
