	async importSkill(params) {
		try {
			let appKey = params.appKey;
			if (params.securityCheck && !appKey) try {
				appKey = (await this._fetchProductConfiguration()).skillSecurityAppKey;
			} catch (err) {
				console.warn("[WorkbuddyAdapter][importSkill] failed to resolve skillSecurityAppKey:", err);
			}
			const paramsWithKey = {
				...params,
				appKey
			};
			const result = this.daemonClient?.skillImport ? await this.daemonClient.skillImport(paramsWithKey) : await this.client.sessions.importSkill(paramsWithKey);
			if (result.success) {
				this.invalidateSkillListCache();
				const installedSkillInfo = result.skillName ? await this.findInstalledSkillInfoByName(result.skillName) : void 0;
				this.reportTelemetry("skill_create", {
					id: result.skillName || "unknown",
					skillId: installedSkillInfo?.skillId,
					skillVersion: installedSkillInfo?.skillVersion,
					source: params.source || "userSettings"
				});
				this.reportTelemetry("skill_action", {
					id: result.skillName || "unknown",
					skillId: installedSkillInfo?.skillId,
					skillVersion: installedSkillInfo?.skillVersion,
					action: "install",
					source: "userSettings"
				});
			}
			return result;
		} catch (error) {
			console.error("[WorkbuddyAdapter] importSkill failed:", error);
			return {
				success: false,
				error: error instanceof Error ? error.message : "Unknown error"
			};
		}
	}
