//#region ../../packages/workbuddy-app/src/i18n/index.ts
init_i18n();
init_src();
instance.use(initReactI18next).init({
	resources: {
		"zh-CN": zh_CN_default,
		"en-US": en_US_default
	},
	lng: localStorage.getItem("workbuddy-language") || "zh-CN",
	fallbackLng: "zh-CN",
	defaultNS: "common",
	interpolation: { escapeValue: false }
});
/**
* 把 desktop 主 i18next 的语言同步到 cb-chat-ui 内置 i18n。
*
* cb-chat-ui 是独立 i18n 系统(自带 locales/zh-cn.json + en.json),CompactDivider
* 等组件从这里取默认 fallback 文案。Desktop 切换语言时必须同步推过去,否则
* Desktop UI 已经是英文界面但 CompactDivider 还显示中文。
*/
function syncCbChatUiLocale(lng) {
	setLocale(lng.toLowerCase().startsWith("zh") ? "zh-cn" : "en");
}
syncCbChatUiLocale(instance.language);
instance.on("languageChanged", syncCbChatUiLocale);
/**
* 把 agent-ui i18n（CODEBUDDY_IDE_STORAGE_LANG）同步到 desktop i18next（workbuddy-language）。
*
* 用户在 Settings 里切换语言时，agent-ui 通过 saveLocale() 写入 CODEBUDDY_IDE_STORAGE_LANG
* 并触发 onLocaleChange，但 desktop 自带的 i18next（菜单栏所用）并不感知此变化。
* 这里把 agent-ui 的语言变更桥接到 i18next.changeLanguage，从而触发 main.tsx 中
* 注册的 languageChanged 监听器（重建 Windows/Linux 菜单栏 + 通知 main 进程更新菜单）。
*/
function applyAgentUiLocaleToI18next(internalLocale) {
	const target = normalizeToWorkbuddyLocale(internalLocale);
	if (target === instance.language) return;
	instance.changeLanguage(target);
	localStorage.setItem("workbuddy-language", target);
}
applyAgentUiLocaleToI18next(getLocale());
onLocaleChange(applyAgentUiLocaleToI18next);
var i18n_default = instance;
//#endregion
//#region ../../packages/workbuddy-app/src/monitor/aegis-bootstrap.ts
init_browser();
/**
* 初始化渲染进程 Aegis 监控。
* - 重复调用安全：aegisMonitor 内部已有 initialized 守卫
* - 失败不抛错：本函数兜底吞掉异常，避免冒到 unhandled rejection
*   （aegisMonitor.initialize 内部仍会 throw，由本函数捕获）
*
* 同时把 renderer 端生成的 Aegis sessionId 推给 main 进程，让两端 SDK 在同一
* session 维度聚合上报：renderer 走 web-sdk session 插件、main 走 electron-sdk
* session 插件，默认是两套独立 ID，必须显式同步才能贯通。
*/
async function initializeRendererAegis(options = {}) {
	try {
		await aegisMonitor.initialize(getMonitoringConfig("workbuddy-main", {
			userId: options.userId,
			version: options.version,
			patchName: options.patchName
		}));
		subscribeSessionIdToMain(options.syncSessionId);
	} catch (error) {
		console.warn("[initializeRendererAegis] aegis init failed (suppressed):", error);
	}
}
/**
* 订阅 renderer Aegis 的 sessionInit / sessionRebuild，并把最新 sessionId
* 通过 daemon RPC 推送给 main 进程。任何一步失败都吞掉，监控不影响主流程。
*
* `onSessionReady` 在 AegisMonitor 内部已用 `firstSessionPromise` race 保证
* 首次 sid 不会因为事件错过 / snapshoot 写入时序差而漏掉，调用方直接订阅即可。
*/
function subscribeSessionIdToMain(push) {
	if (typeof push !== "function") return;
	try {
		let lastPushed = "";
		aegisMonitor.onSessionReady((sessionId) => {
			if (!sessionId || sessionId === lastPushed) return;
			lastPushed = sessionId;
			Promise.resolve(push(sessionId)).catch((error) => {
				console.warn("[initializeRendererAegis] syncSessionId failed:", error);
			});
		});
	} catch (error) {
		console.warn("[initializeRendererAegis] subscribeSessionIdToMain failed:", error);
	}
}
